<template>
  <div :class="cn('flex flex-col gap-1.5 relative w-full')">
    <p v-if="label" class="text-sm">{{ label }}</p>
    <Popover v-model:open="open">
      <PopoverAnchor class="relative">
        <PopoverTrigger as-child>
          <Button
            variant="outline"
            role="combobox"
            :aria-expanded="open"
            :class="cn('w-full h-10 justify-between font-normal', !value && 'text-muted-foreground')"
          >
            <span class="inline-flex items-center overflow-hidden">
              <component :is="icon" v-if="icon" class="me-2 h-4 w-4 shrink-0" />
              <span v-if="selectedItems.length === 0">{{ placeholder }}</span>
              <span v-if="selectedItems.length === 1" class="inline-block truncate max-w-fit">
                {{ selectedItems[0].name ?? selectedItems[0].value }}
                <span v-if="selectedItems[0].subtitle" class="text-muted-foreground">
                  &middot; {{ selectedItems[0].subtitle }}
                </span>
                <!-- Inline rather than a second line: the trigger is a single-line, fixed-height button. -->
                <span v-if="selectedItems[0].caption" class="text-muted-foreground">
                  &middot; {{ selectedItems[0].caption }}
                </span>
              </span>
              <span v-else-if="selectedItems.length > 1">{{
                `${selectedItems.length} ${itemsPluralName || 'items'}`
              }}</span>
            </span>
            <component
              :is="loading ? Spinner : ChevronsUpDownIcon"
              class="ml-4 h-4 w-4 shrink-0"
              :class="!loading && value && value.length > 0 ? 'mr-6' : ''"
            />
          </Button>
        </PopoverTrigger>
        <XIcon
          v-if="!loading && value && value.length > 0"
          class="h-4 w-4 ml-2 shrink-0 absolute right-4 top-[0.75rem] cursor-pointer"
          @click.stop.prevent="onChange(null)"
        />
      </PopoverAnchor>
      <PopoverContent class="w-[var(--reka-popover-trigger-width)] p-0">
        <div
          v-if="loading && flatItems.length === 0"
          class="py-6 px-4 text-center text-sm flex items-center justify-center gap-2"
        >
          <Spinner class="h-4 w-4" />
          <span>Loading...</span>
        </div>
        <div v-else-if="flatItems.length === 0" class="py-6 px-4 text-center text-sm">{{ emptyText }}</div>
        <Command v-else>
          <CommandInput v-if="flatItems.length >= minItemsForSearch" :placeholder="inputPlaceholder" />
          <CommandList
            :class="
              cn(
                'relative z-0',
                flatItems.length >= minItemsForSearch
                  ? 'max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-50px))]'
                  : 'max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-10px))]'
              )
            "
          >
            <CommandEmpty>{{ emptyText }}</CommandEmpty>
            <template v-for="(group, groupIndex) in normalizedGroups" :key="groupIndex">
              <CommandSeparator v-if="groupIndex > 0" />
              <CommandGroup>
                <div v-if="group.label" class="pl-8 pr-2 py-1.5 text-xs font-medium text-muted-foreground">
                  {{ group.label }}
                </div>
                <CommandItem
                  v-for="item in group.items"
                  :key="item.name"
                  :value="item.value"
                  :class="cn('cursor-pointer', item.emphasized && 'font-semibold text-primary')"
                  @select="onChange(item.value)"
                >
                  <CheckIcon
                    :class="
                      cn(
                        'mr-2 h-4 w-4',
                        value && value.find((elem) => elem === item.value) ? 'opacity-100' : 'opacity-0'
                      )
                    "
                  />
                  <img v-if="item.iconSrc" :src="item.iconSrc" alt="" class="h-5 w-5 shrink-0 object-contain" />
                  <span class="flex min-w-0 flex-col">
                    <span class="truncate">
                      {{ item.name }}
                      <span v-if="item.subtitle" class="text-muted-foreground">&middot; {{ item.subtitle }}</span>
                    </span>
                    <span v-if="item.caption" class="truncate text-xs text-muted-foreground">{{ item.caption }}</span>
                  </span>
                </CommandItem>
              </CommandGroup>
            </template>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
    <p v-if="errorMessage && !isOffline" class="p-2 text-sm text-destructive select-none">{{ errorMessage }}</p>
  </div>
</template>

<script setup lang="ts" generic="T extends string">
import { CheckIcon, ChevronsUpDownIcon, XIcon } from 'lucide-vue-next';
import { cn } from '~/components/ui/utils';
import { FetchError } from 'ofetch';
import { Spinner } from '~/assets/icons';
import { PopoverAnchor } from 'reka-ui';

import { getErrorMessage } from '~/utils/getErrorMessage';

const { isOffline } = useNetworkStatus();

interface Props {
  label?: string;
  items?: SelectItem<T>[];
  /** Grouped options: each group is separated by a divider and can have an optional heading. Wins over `items`. */
  groups?: SelectItemGroup<T>[];
  value: T[] | null;
  placeholder: string;
  inputPlaceholder?: string;
  propertyName: string;
  emptyText: string;
  error?: FetchError | string | null;
  nullIsAll: boolean;
  loading?: boolean;
  itemsPluralName: string;
  minItemsForSearch?: number;
  icon?: any;
  isFirstPageOnly?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  placeholder: undefined,
  inputPlaceholder: undefined,
  emptyText: 'No items found.',
  error: undefined,
  label: undefined,
  loading: false,
  minItemsForSearch: 10,
  icon: undefined,
  isFirstPageOnly: true,
  items: () => [],
  groups: undefined,
});
const errorMessage = computed(() => getErrorMessage(props.error));

const emit = defineEmits<{
  change: [value: string | null];
  'open-change': [open: boolean];
}>();

const open = ref(false);
watch(open, (v) => emit('open-change', v));

const route = useRoute();

const normalizedGroups = computed<SelectItemGroup<T>[]>(() => props.groups ?? [{ items: props.items }]);

const flatItems = computed(() => normalizedGroups.value.flatMap((group) => group.items));

const allItems = computed(() => {
  if (props.nullIsAll) {
    return [{ name: props.placeholder, value: null }, ...flatItems.value];
  }
  return flatItems.value;
});

const selectedItems = computed(() => {
  return allItems.value.filter((item) => item.value && props.value?.includes(item.value));
});

async function onChange(value: string | null) {
  const currentQueries = props.value || [];
  const propertyObject = getPropertyObject(currentQueries, value);
  await navigateTo({
    name: route.name,
    params: route.params,
    query: {
      ...route.query,
      ...(props.isFirstPageOnly ? { page: 1 } : {}),
      ...propertyObject,
    },
  });
  emit('change', value);
}

function getPropertyObject(value: string[], newValue: string | null): Record<string, string[] | undefined> {
  let current: string[] = [...value] as T[];
  const propertyNames = props.propertyName.split('|');
  const propertyObject: Record<string, string[] | undefined> = {};
  if (newValue) {
    if (current.includes(newValue)) current = current.filter((item) => item !== newValue);
    else current.push(newValue);
  }
  if (current.length && newValue) {
    if (propertyNames.length > 1) {
      [...current].forEach((propertyValue: string) => {
        const splits = propertyValue.split('|');
        splits.forEach((split, index) => {
          if (!propertyObject[propertyNames[index]]) {
            propertyObject[propertyNames[index]] = [];
          }
          propertyObject[propertyNames[index]]?.push(split);
        });
      });
    } else {
      propertyObject[propertyNames[0]] = current;
    }
  } else {
    propertyNames.forEach((name) => {
      propertyObject[name] = undefined;
    });
  }
  return propertyObject;
}
</script>
